{'Fn::Sub': 'import json\nimport cfnresponse\nimport boto3\n\nec2 = boto3.client("ec2")\n\ndef handler(event, context):\n  print(f"Event : {json.dumps(event)}")\n  response_data = {}\n\n  try:\n    request_type = event["RequestType"]\n    vpce_id = event["ResourceProperties"]["VpcEndpoint"]\n    vpce = ec2.describe_vpc_endpoint_associations(VpcEndpointIds=[f"{vpce_id}"])\n    print(f"VPC Endpoint : {json.dumps(vpce)}")\n\n    if request_type in ["Create", "Update"]:\n      response_data["Message"] = "Custom Resource Created"\n      response_data["DnsName"] = vpce["VpcEndpointAssociations"][0]["DnsEntry"]["DnsName"]\n      response_data["HostedZoneId"] = vpce["VpcEndpointAssociations"][0]["DnsEntry"]["HostedZoneId"]\n    elif request_type == "Delete":\n      response_data["Message"] = "Custom Resource Deleted"\n    cfnresponse.send(event, context, cfnresponse.SUCCESS, response_data)\n  except Exception as e:\n    print(str(e))\n    cfnresponse.send(event, context, cfnresponse.FAILED, response_data, reason=str(e))\n'}